      {"t":"mc","q":"'my house', said the most natural way:","o":["nhà tôi","tôi nhà","của tôi nhà","nhà là tôi"],"why":"Home and family usually drop của: nhà tôi."},
      {"t":"mc","q":"'Whose is this?' (pointing at a thing)","o":["Cái này của ai?","Ai của cái này?","Của ai cái này?","Cái này là ai?"],"why":"ai goes where the owner would go, after của."},
      {"t":"mc","q":"'my friend' =","o":["bạn tôi","tôi bạn","của tôi bạn","tôi của bạn"],"why":"The owner goes after the noun: bạn tôi."},
      {"t":"mc","q":"'This book is mine' =","o":["Quyển sách này là của tôi.","Quyển sách này là tôi.","Tôi quyển sách này.","Quyển sách này tôi của."],"why":"'Mine' is của tôi, after là."},
      {"t":"order","p":"Lan's book","a":["quyển","sách","của","chị","Lan"],"x":["con"],"why":"Noun first, with its classifier quyển, then của and the owner."},
      {"t":"order","p":"This red shirt is mine.","a":["Cái","áo","đỏ","này","là","của","tôi"],"x":["quyển"],"why":"The color goes after the noun, then này: cái áo đỏ này."},
      {"t":"order","p":"Whose motorbike is this?","a":["Chiếc","xe","máy","này","là","của","ai"],"x":["gì"],"why":"whose = của ai; ai goes where the owner would go."},
      {"t":"fill","q":"Đây là nhà __ anh Minh.","p":"This is Minh's house.","a":["của"],"o":["là","có","ai"],"why":"của joins the thing and its owner."},
      {"t":"fill","q":"Quyển sách này là của __?","p":"Whose book is this?","a":["ai"],"o":["gì","không","cái"],"why":"Asking about the owner, a person: ai."},
      {"t":"fill","q":"__ tôi là giáo viên.","p":"My mother is a teacher.","a":["Mẹ"],"o":["Me","Mè","Bố"],"why":"mẹ has the heavy tone mark; me and mè are other words.","strict":true},
      {"t":"type","p":"my friend's motorbike","a":["xe máy của bạn tôi","chiếc xe máy của bạn tôi"],"hint":"xe máy · của · bạn tôi","x":["con"],"why":"Noun first: xe máy, then của and the owner."},
      {"t":"type","p":"Whose cat is this?","a":["Con mèo này là của ai?","Con mèo này của ai?"],"hint":"con mèo · này · của ai","x":["cái"],"why":"con is the classifier for animals, and này goes after the noun."},
      {"t":"type","p":"My father is a doctor.","a":["Bố tôi là bác sĩ.","Bố của tôi là bác sĩ."],"hint":"bố (father) · bác sĩ (doctor)","x":["bò"],"why":"bố has the rising tone mark: bò is a cow.","strict":true}
